import '../models/quiz.dart';
import '../repositories/quiz_repository.dart';
import '../repositories/repository_exception.dart';
import 'fake_config.dart';
import 'samples/quiz_samples.dart';

/// In-memory [QuizRepository]. Quizzes generated by the fake create
/// repository arrive through [addQuiz] (fake-only).
class FakeQuizRepository implements QuizRepository {
  FakeQuizRepository(this._config);

  final FakeConfig _config;
  final List<Quiz> _quizzes = [...sampleQuizzes];
  final Map<String, List<Question>> _questions = {
    sampleQuizId: sampleIntroComputingQuestions,
  };

  /// Adds a new quiz at the top of "My quizzes". Fake-only.
  void addQuiz(Quiz quiz, List<Question> questions) {
    _quizzes.insert(0, quiz);
    _questions[quiz.id] = List.of(questions);
  }

  Quiz _find(String quizId) => _quizzes.firstWhere(
    (q) => q.id == quizId,
    orElse: () => throw RepositoryException('Quiz "$quizId" not found'),
  );

  @override
  Future<List<Quiz>> fetchQuizzes() =>
      _config.answerList('fetchQuizzes', () => List.of(_quizzes));

  @override
  Future<Quiz> fetchQuiz(String quizId) =>
      _config.answer('fetchQuiz', () => _find(quizId));

  @override
  Future<List<Question>> fetchQuestions(String quizId) =>
      _config.answerList('fetchQuestions', () {
        _find(quizId);
        return List.of(_questions[quizId] ?? const <Question>[]);
      });

  @override
  Future<Quiz?> fetchContinueQuiz() => _config.answer<Quiz?>(
    'fetchContinueQuiz',
    () => _find(sampleQuizId),
    empty: () => null,
  );
}
